import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"luarocks test","description":"","frontmatter":{},"headers":[],"relativePath":"luarocks_test.md","filePath":"luarocks_test.md"}'),o={name:"luarocks_test.md"};function c(i,e,p,d,l,r){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="luarocks-test" tabindex="-1">luarocks test <a class="header-anchor" href="#luarocks-test" aria-label="Permalink to &quot;luarocks test&quot;">​</a></h1><p>Run the test suite for the Lua project in the current directory.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p><code>luarocks test [-h] [--test-type &lt;type&gt;] [&lt;rockspec&gt;] [&lt;args&gt;] ...</code></p><p>If the first argument is a rockspec, it will use it to determine the parameters for running tests; otherwise, it will attempt to detect the rockspec.</p><p>Any additional arguments are forwarded to the test suite. To make sure that test suite flags are not interpreted as LuaRocks flags, use <code>--</code> to separate LuaRocks arguments from test suite arguments.</p><h3 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h3><ul><li><code>rockspec</code> - Project rockspec.</li><li><code>args</code> - Test suite arguments.</li></ul><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><ul><li><code>--test-type &lt;type&gt;</code> - Specify the test suite type manually if it was not specified in the rockspec and it could not be auto-detected.</li></ul><h2 id="test-types" tabindex="-1">Test types <a class="header-anchor" href="#test-types" aria-label="Permalink to &quot;Test types&quot;">​</a></h2><p>There are two test types that ship by default with LuaRocks: <code>busted</code> and <code>command</code>. They can be specified explicitly in a rockspec in the <code>test.type</code> field. Custom test types can be loaded using the <code>test_dependencies</code> field; a dependency can declare a new test type by adding a module in the <code>luarocks.test.*</code> namespace; it can then be used as a test type in the rockspec.</p><h3 id="busted-test-type" tabindex="-1"><code>busted</code> test type <a class="header-anchor" href="#busted-test-type" aria-label="Permalink to &quot;\`busted\` test type&quot;">​</a></h3><p>You can enable the <code>busted</code> test type adding a top-level <code>test</code> table in a rockspec and setting its <code>type</code> to <code>busted</code>. The <code>busted</code> type can be auto-detected if the project&#39;s source contains a configuration file called <code>.busted</code>, so if a project has that file <code>luarocks test</code> can be used to launch Busted even if it doesn&#39;t have a <code>test</code> section in the rockspec.</p><p>Here&#39;s an example of a <code>busted</code> test section, also using the <code>flags</code> option to pass extra flags to Busted, and using per-platform overrides.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>test = {</span></span>
<span class="line"><span>   type = &quot;busted&quot;,</span></span>
<span class="line"><span>   platforms = {</span></span>
<span class="line"><span>      windows = {</span></span>
<span class="line"><span>         flags = { &quot;--exclude-tags=ssh,git,unix&quot; }</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      unix = {</span></span>
<span class="line"><span>         flags = { &quot;--exclude-tags=ssh,git&quot; }</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="command-test-type" tabindex="-1"><code>command</code> test type <a class="header-anchor" href="#command-test-type" aria-label="Permalink to &quot;\`command\` test type&quot;">​</a></h3><p>You can enable the <code>command</code> test type adding a top-level <code>test</code> table in a rockspec and setting its <code>type</code> to <code>command</code>. The <code>command</code> type can be auto-detected if the project&#39;s source contains a file called <code>test.lua</code> at the root of the source tree, so if a project has that file <code>luarocks test</code> can be used to run it using the default Lua interpreter even if it doesn&#39;t have a <code>test</code> section in the rockspec.</p><p>The <code>test</code> block for a <code>command</code> test type can take either a <code>script</code> argument, which is a Lua script to be launched using the configured Lua interpreter, or a <code>command</code> argument, which is a command to be launched directly on a shell. Both can take additional arguments via the <code>flags</code> array entry.</p><p>Here is an example using a script:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>test = {</span></span>
<span class="line"><span>   type = &quot;command&quot;,</span></span>
<span class="line"><span>   script = &quot;tests/test_all.lua&quot;,</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>And here is an example using a command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>test = {</span></span>
<span class="line"><span>   type = &quot;command&quot;,</span></span>
<span class="line"><span>   command = &quot;make test&quot;,</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="invocation-example" tabindex="-1">Invocation example <a class="header-anchor" href="#invocation-example" aria-label="Permalink to &quot;Invocation example&quot;">​</a></h2><p>In the following example, assume a project uses Busted as its test tool. The current directory contains the source code of a Lua project with a rockspec in its root, this will run Busted, pass any additional arguments specified in the <code>test.flags</code> field of the rockspec, plus the <code>--exclude-tags=ssh</code> argument given explicitly via the command-line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks test -- --exclude-tags=ssh</span></span></code></pre></div>`,26)])])}const m=t(o,[["render",c]]);export{h as __pageData,m as default};
